'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='golden-frog-science-v1';
const levels=[
 {title:'植物的秘密部件',en:'Plants and Their Parts',page:'24–31',x:28,y:63,audio:'parts',intro:'Look closely at a plant. Which part takes in water from the soil?',zh:'仔细观察植物。哪个部位从土壤中吸收水？',fact:'Roots take in water and minerals. Stems support the plant and carry water. Leaves use light to make food.',factzh:'根吸收水和矿物质；茎支撑植物并运输水；叶利用光制造食物。',words:['roots · 根','stem · 茎','leaves · 叶']},
 {title:'叶片观察员',en:'The Leaf Detectives',page:'25, 32–33',x:40,y:55,audio:'observe',intro:'Observe the two leaves. Compare their shapes before you classify them.',zh:'观察两片叶子的形状，再按同一标准分类。',fact:'We can observe leaf shape and color. We need to touch real leaves to compare how they feel.',factzh:'图中可以观察形状和颜色；判断真实触感需要接触实物，不能只靠图片猜测。',words:['observe · 观察','compare · 比较','classify · 分类']},
 {title:'花朵的秘密任务',en:'From Flower to Fruit',page:'34–41',x:54,y:48,audio:'flowers',intro:'Follow a bean flower. Pollen helps the plant make seeds. What develops around the seeds?',zh:'跟踪一朵豆花。花粉参与种子的形成，种子周围会发育出什么？',fact:'After pollination and fertilization, a bean flower can develop into a pod. The pod is a fruit that protects the seeds.',factzh:'经过授粉与受精，豆花的子房可以发育为豆荚。豆荚是保护种子的果实。',words:['pollen · 花粉','fruit · 果实','seed coat · 种皮']},
 {title:'一颗种子的旅程',en:'A Seed’s Journey',page:'44–49',x:69,y:43,audio:'cycle',intro:'Put the stages of a bean plant in order, starting with a seed.',zh:'从种子开始，排列菜豆的生长阶段。',fact:'A bean seed can germinate, grow into a seedling, and become a mature plant. It can then make flowers, fruits, and new seeds.',factzh:'菜豆种子发芽，长成幼苗和成熟植株，再开花、结果，产生新种子。这个过程需要适宜条件。',words:['germinate · 发芽','seedling · 幼苗','life cycle · 生命周期']},
 {title:'追光的小小实验室',en:'Growing Toward Light',page:'52–57',x:70,y:66,audio:'light',intro:'Move the light. Observe how the young shoot changes its direction.',zh:'移动光源，观察幼嫩茎的生长方向。',fact:'Many young shoots grow toward light. Roots usually grow downward in response to gravity. This diagram is a model, not a real-time experiment.',factzh:'许多幼嫩茎会向光生长；根通常响应重力向下生长。此处为概念模型，并非真实实验记录。',words:['light · 光','gravity · 重力','environment · 环境']},
 {title:'植物研究员挑战',en:'The Field Research Challenge',page:'66–69',x:55,y:75,audio:'challenge',intro:'Use what you have discovered. Read the evidence and explain your choices.',zh:'运用你的发现，根据证据解释选择。',fact:'A good scientist observes carefully, compares evidence, and explains a conclusion. Keep asking questions!',factzh:'好的科学探究需要细心观察、比较证据，并解释结论。继续保持好奇！',words:['evidence · 证据','predict · 预测','explain · 解释']}
];
function freshProfile(){return {completed:[],built:[],mode:'guided',voice:'af_heart',animals:validateAnimals(undefined),earth:validateEarth(undefined),fossils:validateFossils(undefined),resources:validateResources(undefined),motion:validateMotion(undefined),forces:validateForces(undefined),expedition:validateExpedition(undefined),final:validateFinal(undefined),learning:validateLearning(undefined)}}
function fresh(){return {version:1,active:'child',profiles:{child:freshProfile(),adult:{...freshProfile(),mode:'challenge'}}}}
function validate(s){if(!s||s.version!==1||!['child','adult'].includes(s.active))throw Error('存档格式不匹配');for(const name of ['child','adult']){let p=s.profiles?.[name];if(!p||!Array.isArray(p.completed)||!Array.isArray(p.built)||!['guided','challenge'].includes(p.mode)||!['af_heart','af_bella'].includes(p.voice))throw Error('存档内容不完整');if(p.completed.some((x,i)=>x!==i)||p.completed.length>6||p.built.some(x=>!['greenhouse','station','library'].includes(x))||new Set(p.built).size!==p.built.length)throw Error('存档进度无效');p.animals=validateAnimals(p.animals);p.earth=validateEarth(p.earth);p.fossils=validateFossils(p.fossils);p.resources=validateResources(p.resources);p.motion=validateMotion(p.motion);p.forces=validateForces(p.forces);p.expedition=validateExpedition(p.expedition);p.final=validateFinal(p.final);p.learning=validateLearning(p.learning);const cost=p.built.reduce((n,id)=>n+buildings.find(b=>b.id===id).cost,0);if(cost>(p.completed.length+p.animals.completed.length+p.earth.completed.length+p.fossils.completed.length+p.resources.completed.length+p.motion.completed.length+p.forces.completed.length+p.expedition.completed.length)*30)throw Error('存档积分无效')}return s}
const buildings=[{id:'greenhouse',icon:'♧',title:'种子温室',en:'Seed Greenhouse',cost:20,desc:'给第一颗研究种子一个家。',built:'温室已建成，新的观察从这里开始。'},{id:'station',icon:'⌂',title:'野外观察站',en:'Field Station',cost:40,desc:'把每一次发现，变成下一次探索的起点。',built:'观察站已建成，研究设备准备就绪。'},{id:'library',icon:'▤',title:'自然图书馆',en:'Nature Library',cost:60,desc:'收藏植物知识与探险记录。',built:'图书馆已建成，发现手册有了新家。'}];
let state=fresh(),storageOK=true;try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw))}catch(e){storageOK=false;$('#saveLabel').textContent='存档读取失败，请先导出备份'}
function profile(){return state.profiles[state.active]}
function points(){return (profile().completed.length+profile().animals.completed.length+profile().earth.completed.length+profile().fossils.completed.length+profile().resources.completed.length+profile().motion.completed.length+profile().forces.completed.length+profile().expedition.completed.length)*30-profile().built.reduce((n,id)=>n+buildings.find(b=>b.id===id).cost,0)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('#saveLabel').textContent='本机自动存档'}catch(e){storageOK=false;$('#saveLabel').textContent='未能保存，请导出存档';toast('浏览器存储不可用，请导出备份。')}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
// One user-activated, native player for both chapters, including iPad Safari.
let playing;
const narration=document.createElement('section');narration.className='narration';narration.hidden=true;
narration.innerHTML='<div class="narration-heading"><strong>Listen · 英文配音</strong><span role="status" aria-live="polite"></span></div><audio controls playsinline preload="none" aria-label="English narration / 英文配音"></audio><button class="text-button" type="button">Replay · 重新播放</button>';
const narrationAudio=narration.querySelector('audio'),narrationStatus=narration.querySelector('[role="status"]');
document.body.append(narration);
function mountNarration(){
 const host=document.querySelector('dialog[open]')||document.body;
 if(narration.parentElement!==host){const header=host.querySelector('.lesson-header');if(header)header.after(narration);else host.append(narration);}
}
function stopAudio(){narrationAudio.pause();playing=null;narration.hidden=true;}
function playNarration(){
 playing=narrationAudio;narration.hidden=false;mountNarration();
 narrationStatus.textContent='Loading… · 正在加载';
 const request=narrationAudio.play();
 if(request)request.catch(()=>{if(playing===narrationAudio)narrationStatus.textContent='Tap ▶ below to retry. 请点下方播放键重试，并检查设备音量。';});
}
narration.querySelector('button').onclick=()=>{narrationAudio.currentTime=0;playNarration();};
narrationAudio.addEventListener('playing',()=>{narrationStatus.textContent='Playing · 正在播放';});
narrationAudio.addEventListener('ended',()=>{narrationStatus.textContent='Finished · 播放完毕，可重听';});
narrationAudio.addEventListener('error',()=>{narrationStatus.textContent='Audio could not load. 音频加载失败，请检查网络后点重新播放。';});
function speak(id,rate=1){
 stopAudio();narrationAudio.src=new URL(`audio/${profile().voice}-${id}.mp3${/^[frmgexl]/.test(id)?'?v=10':''}`,document.baseURI).href;
 narrationAudio.load();narrationAudio.playbackRate=rate;playNarration();
 narration.scrollIntoView({block:'nearest'});
}

function render(){const p=profile(),n=p.completed.length;$('#xp').textContent=points();$('#badges').textContent=n+p.animals.completed.length+p.earth.completed.length+p.fossils.completed.length+p.resources.completed.length+p.motion.completed.length+p.forces.completed.length+p.expedition.completed.length;$('#profileBtn').textContent=state.active==='child'?'◉ 小探险家':'◉ 成人研究员';$('#mapNodes').innerHTML=levels.map((l,i)=>`<button class="node ${i<n?'done':i===n?'current':'locked'}" style="left:${l.x}%;top:${l.y}%" ${i>n?'disabled':''} data-level="${i}" aria-label="第${i+1}关 ${l.title}${i<n?'，已完成':i>n?'，尚未解锁':''}">${i<n?'✓':i>n?'♧':i+1}<span>${["Plant parts","Leaves","Flowers","Life cycle","Light lab","Challenge"][i]}<small>${l.title}</small></span></button>`).join('');$$('[data-level]').forEach(b=>b.onclick=()=>openLevel(+b.dataset.level));$('#nextTitle').textContent=n<6?levels[n].en:'An island of discoveries';$('#nextSubtitle').textContent=n<6?levels[n].title:'整座岛，都是你的发现';$('#startBtn').innerHTML=n<6?'Explore <small>开始探险</small> ↗':'Explore again <small>重游第一关</small> ↗';$('#progressText').textContent=`章节进度 ${n} / 6`;$('#progressBar').style.width=`${n/6*100}%`;renderBase();renderJournal();window.Animals?.render();window.Learning?.render()}
function switchTab(tab){$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));for(const t of ['map','base','journal','learn']){const v=$('#'+t+'View');if(v)v.hidden=t!==tab;}if($('#chapterPicker'))$('#chapterPicker').hidden=tab==='learn';}
$$('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('.brand').onclick=e=>{e.preventDefault();switchTab('map')};$('#startBtn').onclick=()=>openLevel(Math.min(profile().completed.length,5)===5&&profile().completed.length===6?0:profile().completed.length);
function continueExploring(){if(profile().final.attempts.length&&window.Learning){Learning.open("plan");return;}if(profile().expedition.completed.length===7&&window.FinalChallenge){Animals.selectChapter(9);return;}if(profile().forces.completed.length===20&&window.Expedition)return window.Expedition.go();if(profile().motion.completed.length===20&&window.Forces)return window.Forces.go();if(profile().resources.completed.length===24&&window.Motion)return window.Motion.go();if(profile().fossils.completed.length===12&&window.Resources)return window.Resources.go();if(profile().earth.completed.length===12&&window.Fossils)return window.Fossils.go();if(profile().animals.completed.length===12&&window.Earth)return window.Earth.go();if(profile().completed.length===6&&window.Animals)return window.Animals.go();switchTab('map');openLevel(profile().completed.length<6?profile().completed.length:0)}
function renderBase(){const p=profile();$('#baseView').innerHTML=`<div class="section-heading"><p class="eyebrow">YOUR RESEARCH HOME</p><h2>Build your research base<small class="title-zh">让每一个发现，长成新的可能。</small></h2><p>Earn 30 points for each new discovery. Choose what to build next.<br>首次完成每关获得 30 积分；重玩不重复计分。当前可用：${points()} 积分。</p><button class="secondary" data-continue>Explore & earn points <small>去探险，赚取积分</small> ↗</button></div><div class="base-grid">${buildings.map(b=>{const built=p.built.includes(b.id),gap=Math.max(0,b.cost-points());return `<article class="build-card ${built?'built':''}"><div class="building">${b.icon}</div><p class="eyebrow">${built?'READY TO VISIT':'BUILDING PLAN'}</p><h3>${b.en}<small class="title-zh">${b.title}</small></h3><p>${built?b.built:b.desc}</p><p>${built?'✓ Built · 已建成':`${b.cost} points · ${gap?'还差 '+gap+' 积分':'可以建设了'}`}</p><button class="${built?'secondary':'primary'}" data-build="${b.id}">${built?'Visit · 进入':gap?'Earn points · 去探索 ↗':'Build · 建设 ✦'}</button></article>`}).join('')}</div>`;$('#baseView [data-continue]').onclick=continueExploring;$$('[data-build]').forEach(b=>b.onclick=()=>{const item=buildings.find(x=>x.id===b.dataset.build);if(p.built.includes(item.id)){if(item.id==='library')switchTab('journal');else if(item.id==='station'&&window.Animals){window.Animals.go();}else openLevel(item.id==='greenhouse'?0:Math.min(1,p.completed.length));return}if(points()<item.cost){continueExploring();return}p.built.push(item.id);save();render();toast('✦ '+item.en+' built! '+item.title+'已建成，点击进入开始观察。')})}
function renderJournal(){const p=profile();$('#journalView').innerHTML=`<div class="section-heading"><p class="eyebrow">THE DISCOVERY JOURNAL</p><h2>Your discoveries<small class="title-zh">你发现的，都会在这里生根。</small></h2><p>Collect science stories and useful words as you explore.<br>完成任务后，收集科学解释和英语词汇。</p><button class="primary" data-continue>${p.completed.length<6?'Continue exploring':'Explore again'} <small>继续探索地图</small> ↗</button></div><div class="journal-grid">${levels.map((l,i)=>`<article class="journal-card"><p class="eyebrow">DISCOVERY ${String(i+1).padStart(2,'0')}</p><h3>${l.en}<small class="title-zh">${l.title}</small></h3><p>${p.completed.includes(i)?l.fact:'Not discovered yet · 尚未发现'}</p>${p.completed.includes(i)?`<p>${l.factzh}</p><p>${l.words.join(' / ')}</p><button class="secondary" data-review="${i}">Revisit <small>重温发现</small> ↗</button>`:i===p.completed.length?`<button class="secondary" data-review="${i}">Start this discovery <small>开始这一关</small> ↗</button>`:'<p>Complete the earlier missions to unlock.<br>按地图顺序完成前面的任务即可解锁。</p>'}</article>`).join('')}</div>`;$('#journalView [data-continue]').onclick=continueExploring;$$('[data-review]').forEach(b=>b.onclick=()=>openLevel(+b.dataset.review))}

let current=0,step=0,chosen=[],observed=new Set(),quizScore=0;
const plant=`<figure class="photo-study"><div class="annotated-plant"><img src="assets/plant.jpg" alt="Real avocado seedling with leaves, stem, seed and exposed roots"><svg viewBox="0 0 300 472" aria-hidden="true"><g fill="none" stroke="#486b46" stroke-width="1.5"><path d="M76 48H115L150 60"/><path d="M223 245H184L151 222"/><path d="M83 432H120L151 437"/></g><g fill="#244a38" font-size="15" font-family="Segoe UI,sans-serif"><text x="8" y="44">Leaves</text><text x="229" y="249">Stem</text><text x="18" y="428">Roots</text></g></svg></div><figcaption><strong>Avocado seedling <small>牛油果幼苗</small></strong><span>Roots are exposed here so we can observe them.<br>根部露出，方便观察。大圆块是种子，不是根。</span><a href="photo-credits.html" target="_blank" rel="noopener">Photo: Mark Hofstetter · CC BY 2.5 ↗</a></figcaption></figure>`;
const leafPhotos=`<figure class="photo-study"><div class="leaf-photos"><div><img src="assets/willow.jpg" alt="A real narrow green white willow leaf"><strong>A · Willow</strong><small>柳叶</small></div><div><img src="assets/ginkgo.jpg" alt="A real fan-shaped green ginkgo leaf"><strong>B · Ginkgo</strong><small>银杏叶</small></div></div><figcaption><span>Compare shapes, not sizes. Photos use different scales.<br>比较形状；两张照片的缩放比例不同。</span><a href="photo-credits.html" target="_blank" rel="noopener">Photos: S Sepp / Brayden A. · Credits ↗</a></figcaption></figure>`;

function shell(body){const l=levels[current];$('#lessonContent').innerHTML=`<div class="lesson-intro"><div><h3>${l.intro}</h3>${profile().mode==='guided'?`<div class="zh">${l.zh}</div>`:''}</div><button class="listen" id="listenIntro">▷ Listen <small>听任务</small></button></div>${profile().mode==='challenge'?'<div class="challenge-note">独立挑战：先说出你的预测，再操作或选择；完成后用英语解释你的证据。</div>':''}${body}<div id="feedback" class="feedback" role="status" aria-live="polite"></div><div class="lesson-bottom"><span class="source-note">G2 · Chapter 1 · 教材印刷页 ${l.page} · 原创伴学任务</span><button class="primary" id="checkBtn">Check <small>检查发现</small> ↗</button></div>`;$('#listenIntro').onclick=()=>speak(l.audio);$('#checkBtn').onclick=check}
function openLevel(i){if(i>profile().completed.length||i<0||i>=6)return;stopAudio();current=i;step=0;chosen=[];observed=new Set();quizScore=0;$('#lessonKicker').textContent=`FIELD MISSION ${String(i+1).padStart(2,'0')} / 06`;$('#lessonTitle').innerHTML=levels[i].en+'<small class="title-zh">'+levels[i].title+'</small>';drawTask();if(!$('#lessonDialog').open)$('#lessonDialog').showModal()}
function feedback(t,bad=false){$('#feedback').textContent=t;$('#feedback').classList.toggle('bad',bad)}
function choices(options){return `<div class="choices">${options.map((x,i)=>`<button class="choice" data-answer="${i}">${x}</button>`).join('')}</div>`}
function bindChoices(){chosen=[];$$('[data-answer]').forEach(b=>b.onclick=()=>{chosen=[+b.dataset.answer];$$('[data-answer]').forEach(x=>x.classList.toggle('selected',x===b));feedback('')})}
const partsQ=[['Which part takes in water and minerals?',['Roots','Leaves','Flowers'],0],['Which part supports the plant and carries water?',['Seed coat','Stem','Petals'],1],['Where does a green plant mainly make its food?',['In the soil','In the roots','In its leaves'],2]];
const leafQ=[['Which feature can you compare in this picture?',['Leaf shape','The smell of the leaves','How soft the leaves feel'],0],['How should we describe the two leaves?',['They have the same shape.','Both are green, but their shapes are different.','They must come from the same plant.'],1]];
const flowerQ=[['What can a bean flower develop into?',['A pod with seeds','A new root','A leaf without seeds'],0],['What does the seed coat do?',['Makes pollen','Protects the seed','Absorbs sunlight for the flower'],1]];
const finalQ=[['A plant gets enough light, but its soil is very dry. Which part takes in water when you water it?',['The petals','The roots','The fruit'],1],['Your bean plant makes seeds. What kind of plant can grow from those seeds?',['A bean plant','An oak tree','Any kind of plant'],0],['You want to test how light affects a young shoot. What is a fair comparison?',['Change light and water together.','Use a bean plant and a cactus.','Use similar plants, change the light, and keep other conditions the same.'],2],['Which sentence explains the evidence correctly?',['Plants eat soil through their roots.','Every seed needs light to germinate.','Many young shoots bend toward light as they grow.'],2]];
function drawTask(){if(current===0){let q=partsQ[step];shell(`<div class="task-grid">${plant}<div><p class="quiz-count">观察 ${step+1} / 3</p><p class="task-prompt">${q[0]}</p>${choices(q[1])}</div></div>`);bindChoices()}
else if(current===1){let q=leafQ[step];shell(`<div class="task-grid">${leafPhotos}<div><p class="quiz-count">观察 ${step+1} / 2</p><p class="task-prompt">${q[0]}</p>${choices(q[1])}</div></div>`);bindChoices()}
else if(current===2){let q=flowerQ[step];shell(`<div class="task-grid"><div class="fruit-scene" aria-label="豆花到含种子的豆荚"><span>🌼</span><b>→</b><span>🫛</span></div><div><p class="quiz-count">研究 ${step+1} / 2</p><p class="task-prompt">${q[0]}</p>${choices(q[1])}</div></div>`);bindChoices()}
else if(current===3){shell(`<div class="task-grid"><div><p class="task-prompt">Tap the stages in the order they happen.</p><p class="zh">依次点选生长阶段。点“重新排列”可以重试。</p><div class="chips">${['A mature plant with flowers','A seedling','A seed','A germinating seed'].map((x,i)=>`<button class="chip" data-stage="${i}">${x}</button>`).join('')}</div><button class="secondary" id="resetSequence" style="margin-top:20px">重新排列</button></div><div id="sequenceSlots">${[1,2,3,4].map(i=>`<div class="sequence-slot"><span class="number-tag">${i}</span>选择第 ${i} 个阶段</div>`).join('')}</div></div>`);$$('[data-stage]').forEach(b=>b.onclick=()=>{chosen.push(+b.dataset.stage);b.disabled=true;const slot=$$('.sequence-slot')[chosen.length-1];slot.classList.add('filled');slot.innerHTML=`<span class="number-tag">${chosen.length}</span>${b.textContent}`});$('#resetSequence').onclick=()=>{chosen=[];drawTask()}}
else if(current===4){shell(`<div class="task-grid"><div><div class="experiment"><span class="sun" id="sun">☀</span><svg viewBox="0 0 300 210" aria-label="向光生长示意模型"><path d="M150 176v29m0-24-28 21m28-19 28 21" fill="none" stroke="#b18c56" stroke-width="4"/><g id="shoot"><path d="M150 176V63" stroke="#61874c" stroke-width="7"/><path d="M150 116Q98 115 101 79Q137 76 150 116m0-30q44-1 47-37-36-2-47 37" fill="#85ad61"/></g><path d="M45 179H260" stroke="#baaa7f" stroke-width="2"/></svg></div><div class="control-row"><button class="secondary" data-light="left">☀ 光在左侧</button><button class="secondary" data-light="right">光在右侧 ☀</button></div><p class="zh">生长方向示意 · 时间经过压缩，不显示真实生长速度。</p></div><div><p class="task-prompt">Observe both light positions. What changes?</p><p class="zh">先观察左右两种光源位置，再回答。</p>${choices(['The roots turn toward the light.','The young shoot bends toward the light.','The whole plant moves across the soil.'])}<table class="data-table"><thead><tr><th>光源</th><th>观察记录</th></tr></thead><tbody><tr><td>左侧</td><td id="recordLeft">尚未观察</td></tr><tr><td>右侧</td><td id="recordRight">尚未观察</td></tr></tbody></table></div></div>`);bindChoices();$$('[data-light]').forEach(b=>b.onclick=()=>{let side=b.dataset.light;observed.add(side);$('#sun').style.left=side==='left'?'15%':'75%';$('#shoot').style.transform=`rotate(${side==='left'?-22:22}deg)`;$('#record'+(side==='left'?'Left':'Right')).textContent=side==='left'?'茎向左弯曲':'茎向右弯曲';feedback('继续观察，然后选择与你的观察一致的解释。')})}
else{const q=finalQ[step];shell(`<div class="quiz-count">证据挑战 ${step+1} / ${finalQ.length}</div><p class="task-prompt">${q[0]}</p>${choices(q[1])}`);bindChoices()}}
